"""Offline complete-call result handling example."""

from __future__ import annotations

import json
from collections.abc import Iterable

from loushang.ai import AssistantMessage, CallOptions, TextPart, get_model

PROVIDER_ID = "moonshot"
ENDPOINT_ID = "openai-completions"
MODEL_ID = "kimi-k2.6"
SYSTEM_PROMPT = "You are an example assistant."
USER_PROMPT = "请用两句话介绍你自己，并说明 1 + 1 等于几。"
MAX_TOKENS = 256


def _build_context() -> dict[str, object]:
    return {
        "system_prompt": SYSTEM_PROMPT,
        "messages": [{"role": "user", "content": USER_PROMPT}],
    }


def _build_options() -> CallOptions:
    return CallOptions(max_output_tokens=MAX_TOKENS)


def _offline_message() -> AssistantMessage:
    return AssistantMessage(
        role="assistant",
        content=[TextPart(type="text", text="mock hello from offline fixture")],
        api=ENDPOINT_ID,
        provider=PROVIDER_ID,
        endpoint=ENDPOINT_ID,
        model=MODEL_ID,
        response_id="offline-complete-demo",
        usage=None,
        stop_reason="stop",
        error_message=None,
        timestamp=0.0,
    )


def _iter_text(parts: Iterable[object]) -> str:
    texts: list[str] = []
    for part in parts:
        if getattr(part, "type", None) == "text":
            texts.append(part.text)
    return "".join(texts)


def inspect_complete() -> dict[str, object]:
    model = get_model(PROVIDER_ID, ENDPOINT_ID, MODEL_ID)
    message = _offline_message()
    context = _build_context()
    messages = context["messages"]
    return {
        "model": f"{model.provider_id}:{model.endpoint_id}:{model.id}",
        "maxOutputTokens": _build_options().max_output_tokens,
        "messageCount": len(messages) if isinstance(messages, list) else 0,
        "responseId": message.response_id,
        "stopReason": message.stop_reason,
        "text": _iter_text(message.content),
    }


def main() -> None:
    print(json.dumps(inspect_complete(), ensure_ascii=False, sort_keys=True))


if __name__ == "__main__":
    main()

from __future__ import annotations

import os
import time
from collections.abc import Mapping
from dataclasses import dataclass
from pathlib import Path

from loushang.ai.auth.core import _generic_oauth_provider, get_oauth_provider
from loushang.ai.auth.credentials import (
    AuthCredential,
    OAuthCredential,
)
from loushang.ai.auth.errors import (
    CredentialExpiredError,
    InvalidCredentialError,
    MissingCredentialError,
    RefreshFailedError,
)
from loushang.ai.auth.oauth.base import OAuthProvider
from loushang.ai.auth.registry import AuthRegistry, get_auth_registry
from loushang.ai.auth.sources import (
    CredentialSource,
    get_credential_source,
)
from loushang.ai.auth.store import (
    FileCredentialStore,
    load_credential_file,
    save_credential_file,
)
from loushang.ai.auth.support import normalize_auth_kind, resolve_api_key_auth


@dataclass(frozen=True, slots=True)
class _ResolvedCredential:
    credential: OAuthCredential
    source: str
    path: Path | None = None


async def resolve_auth(
    model,
    *,
    options=None,
    credential: OAuthCredential | None = None,
    credential_file: str | Path | None = None,
    store: FileCredentialStore | None = None,
    providers: Mapping[str, OAuthProvider] | None = None,
    sources: Mapping[str, CredentialSource] | None = None,
    auth_registry: AuthRegistry | None = None,
    env: Mapping[str, str] | None = None,
    refresh_window_seconds: float = 60.0,
    now: float | None = None,
) -> AuthCredential | None:
    """Resolve request auth by explicit-auth, credential, file, store, then env."""

    declaration = getattr(model, "auth", None)
    explicit_auth = getattr(options, "auth", None) if options is not None else None
    if explicit_auth is not None:
        return explicit_auth

    explicit_credential = credential
    if explicit_credential is None and options is not None:
        explicit_credential = getattr(options, "credential", None)
    explicit_file = credential_file
    if explicit_file is None and options is not None:
        explicit_file = getattr(options, "credential_file", None)

    kind = normalize_auth_kind(getattr(declaration, "kind", None))
    if declaration is None or kind == "none":
        if explicit_credential is None and explicit_file is None:
            return None
        kind = "oauth"
    if kind == "api_key":
        if explicit_credential is not None or explicit_file is not None:
            raise InvalidCredentialError(
                "OAuth credentials cannot authenticate a model configured for API key auth.",
                provider=getattr(model, "provider_id", None),
                endpoint=getattr(model, "endpoint_id", None),
                model=getattr(model, "id", None),
                details={"recovery": "reconfigure"},
            )
        return resolve_api_key_auth(
            declaration,
            model=model,
            env=os.environ if env is None else env,
        )
    if kind != "oauth":
        raise InvalidCredentialError(
            "Model has an unsupported authentication kind.",
            provider=getattr(model, "provider_id", None),
            endpoint=getattr(model, "endpoint_id", None),
            model=getattr(model, "id", None),
            details={"auth_kind": str(kind), "recovery": "reconfigure"},
        )

    registry = auth_registry or get_auth_registry()
    source_adapter = registry.resolve_auth_adapter(model)
    legacy_provider_id = _oauth_provider_id(model, declaration)
    if source_adapter is None:
        source_adapter = _legacy_source_for(
            legacy_provider_id,
            sources,
            registry=registry,
            model=model,
        )
    elif sources is not None and source_adapter.id in sources:
        source_adapter = sources[source_adapter.id]
    provider_id = source_adapter.id if source_adapter is not None else legacy_provider_id
    resolved = _load_oauth_credential(
        provider_id,
        credential=explicit_credential,
        credential_file=explicit_file,
        store=store,
        source_adapter=source_adapter,
    )
    if resolved is None:
        recovery, source_id = _credential_recovery(
            source_adapter,
        )
        details = {
            "oauth_provider": provider_id,
            "recovery": recovery,
        }
        if source_id is not None:
            details["credential_source"] = source_id
        raise MissingCredentialError(
            "Model requires an OAuth credential but none was found.",
            provider=getattr(model, "provider_id", None),
            endpoint=getattr(model, "endpoint_id", None),
            model=getattr(model, "id", None),
            details=details,
        )
    _validate_credential_provider(resolved.credential, provider_id, model=model)
    timestamp = time.time() if now is None else now
    prepared = await _refresh_if_needed(
        resolved,
        provider_id=provider_id,
        store=store,
        providers=providers,
        source_adapter=source_adapter,
        refresh_window_seconds=refresh_window_seconds,
        now=timestamp,
        model=model,
    )
    return prepared.to_auth()


def _load_oauth_credential(
    provider_id: str,
    *,
    credential: OAuthCredential | None,
    credential_file: str | Path | None,
    store: FileCredentialStore | None,
    source_adapter: CredentialSource | None,
) -> _ResolvedCredential | None:
    if credential is not None:
        if not isinstance(credential, OAuthCredential):
            raise InvalidCredentialError(
                "credential must be OAuthCredential.",
                details={"recovery": "reconfigure"},
            )
        return _ResolvedCredential(credential=credential, source="explicit")
    if credential_file is not None:
        path = Path(credential_file).expanduser()
        if source_adapter is not None:
            return _ResolvedCredential(
                credential=source_adapter.load_file(path),
                source="credential_source_file",
                path=path,
            )
        return _ResolvedCredential(
            credential=load_credential_file(path),
            source="credential_file",
            path=path,
        )
    resolved_store = store or FileCredentialStore()
    stored = resolved_store.load(provider_id)
    if stored is not None:
        return _ResolvedCredential(credential=stored, source="default_store")
    if source_adapter is not None:
        external = source_adapter.load()
        if external is not None:
            return _ResolvedCredential(
                credential=external,
                source="credential_source",
            )
    return None


async def _refresh_if_needed(
    resolved: _ResolvedCredential,
    *,
    provider_id: str,
    store: FileCredentialStore | None,
    providers: Mapping[str, OAuthProvider] | None,
    source_adapter: CredentialSource | None,
    refresh_window_seconds: float,
    now: float,
    model,
) -> OAuthCredential:
    credential = resolved.credential
    recovery, source_id = _credential_recovery(
        source_adapter,
    )
    recovery_details = {
        "oauth_provider": provider_id,
        "recovery": recovery,
    }
    if source_id is not None:
        recovery_details["credential_source"] = source_id
    if not credential.expires_within(refresh_window_seconds, now=now):
        return credential
    if resolved.source in {
        "credential_source",
        "credential_source_file",
    } and (
        source_adapter is None
        or getattr(source_adapter, "supports_refresh", False) is not True
    ):
        raise CredentialExpiredError(
            "OAuth credential source does not support refresh.",
            provider=getattr(model, "provider_id", None),
            endpoint=getattr(model, "endpoint_id", None),
            model=getattr(model, "id", None),
            details=recovery_details,
        )
    if credential.refresh_token is None:
        raise CredentialExpiredError(
            "OAuth credential is expired or near expiry and has no refresh token.",
            provider=getattr(model, "provider_id", None),
            endpoint=getattr(model, "endpoint_id", None),
            model=getattr(model, "id", None),
            details=recovery_details,
        )
    adapter = _provider_for(provider_id, providers, model=model)
    if adapter is None:
        raise RefreshFailedError(
            "OAuth credential needs refresh but no provider adapter is registered.",
            provider=getattr(model, "provider_id", None),
            endpoint=getattr(model, "endpoint_id", None),
            model=getattr(model, "id", None),
            details=recovery_details,
        )
    try:
        refreshed = await adapter.refresh(credential)
    except RefreshFailedError:
        raise
    except Exception as error:
        raise RefreshFailedError(
            "OAuth credential refresh failed.",
            provider=getattr(model, "provider_id", None),
            endpoint=getattr(model, "endpoint_id", None),
            model=getattr(model, "id", None),
            details={
                "oauth_provider": provider_id,
                "cause": type(error).__name__,
                "recovery": "login",
            },
        ) from error
    _validate_credential_provider(refreshed, provider_id, model=model)
    if refreshed.is_expired(now=now):
        raise RefreshFailedError(
            "OAuth provider returned an expired credential.",
            provider=getattr(model, "provider_id", None),
            endpoint=getattr(model, "endpoint_id", None),
            model=getattr(model, "id", None),
            details={"oauth_provider": provider_id, "recovery": "login"},
        )
    if resolved.source == "credential_file" and resolved.path is not None:
        save_credential_file(resolved.path, refreshed)
    elif resolved.source == "default_store":
        (store or FileCredentialStore()).save(refreshed)
    return refreshed


def _oauth_provider_id(model, declaration) -> str:
    configured = getattr(declaration, "provider", None)
    if isinstance(configured, str) and configured.strip():
        return configured.strip()
    provider_id = getattr(model, "provider_id", None)
    if not isinstance(provider_id, str) or not provider_id:
        raise InvalidCredentialError(
            "OAuth model has no provider identity.",
            details={"recovery": "reconfigure"},
        )
    return provider_id


def _provider_for(
    provider_id: str,
    providers: Mapping[str, OAuthProvider] | None,
    *,
    model,
) -> OAuthProvider | None:
    if providers is not None and provider_id in providers:
        return providers[provider_id]
    registered = get_oauth_provider(provider_id)
    if registered is not None:
        return registered
    return _generic_oauth_provider(model)


def _legacy_source_for(
    provider_id: str,
    sources: Mapping[str, CredentialSource] | None,
    *,
    registry: AuthRegistry,
    model,
) -> CredentialSource | None:
    source: CredentialSource | None
    if sources is not None and provider_id in sources:
        source = sources[provider_id]
    else:
        source = registry.get_credential_source(provider_id)
        if source is None:
            source = get_credential_source(provider_id)
    if source is None or not source.matches(model):
        return None
    return source


def _credential_recovery(
    source: CredentialSource | None,
) -> tuple[str, str | None]:
    if source is None:
        return "login", None
    recovery = getattr(source, "recovery", "external_login")
    if not isinstance(recovery, str) or not recovery:
        recovery = "external_login"
    return recovery, source.id


def _validate_credential_provider(
    credential: OAuthCredential,
    provider_id: str,
    *,
    model,
) -> None:
    if not isinstance(credential, OAuthCredential):
        raise InvalidCredentialError(
            "OAuth provider returned an unsupported credential.",
            details={"recovery": "reconfigure"},
        )
    if credential.provider != provider_id:
        raise InvalidCredentialError(
            "OAuth credential provider does not match the model auth provider.",
            provider=getattr(model, "provider_id", None),
            endpoint=getattr(model, "endpoint_id", None),
            model=getattr(model, "id", None),
            details={
                "credential_provider": credential.provider,
                "oauth_provider": provider_id,
                "recovery": "reconfigure",
            },
        )


__all__ = ["resolve_auth"]

from __future__ import annotations

from typing import Any, Literal, cast

from loushang.ai.model.domain import AnthropicMessagesConfig
from loushang.ai.options import CacheRetention
from loushang.ai.protocols._helpers import (
    get_header_case_insensitive,
    set_header_case_insensitive,
)
from loushang.ai.utils import sanitize_surrogates


class AnthropicMessagesProtocol:
    """
    Anthropic provider shared helpers to align semantics with pi-ai across SDK/HTTPX impls.
    """

    @staticmethod
    def supports_adaptive_thinking(
        adapter_config: AnthropicMessagesConfig | None,
    ) -> bool:
        return (
            adapter_config is not None
            and adapter_config.thinking_mode == "adaptive"
        )

    @staticmethod
    def map_thinking_level_to_effort(
        level: str | None,
        adapter_config: AnthropicMessagesConfig | None,
    ) -> Literal["low", "medium", "high", "xhigh", "max"] | None:
        if level is None or adapter_config is None:
            return None
        effort = adapter_config.reasoning_effort_map.get(level)
        if effort in ("low", "medium", "high", "xhigh", "max"):
            return cast(Literal["low", "medium", "high", "xhigh", "max"], effort)
        return None

    @staticmethod
    def resolve_cache_retention(
        cache_retention: CacheRetention | None,
    ) -> CacheRetention:
        if cache_retention in ("none", "short", "long"):
            return cache_retention  # type: ignore[return-value]
        return "short"  # default

    @classmethod
    def get_cache_control(
        cls,
        base_url: str | None,
        cache_retention: CacheRetention | None,
        *,
        supports_long_cache_retention: bool | None = None,
    ):
        retention = cls.resolve_cache_retention(cache_retention)
        if retention == "none":
            return {"retention": retention, "cacheControl": None}
        supports_long = bool(supports_long_cache_retention)
        ttl = "1h" if retention == "long" and supports_long else None
        cache_control = {"type": "ephemeral", **({"ttl": ttl} if ttl else {})}
        return {"retention": retention, "cacheControl": cache_control}

    @staticmethod
    def merge_headers(*sources: dict[str, str] | None) -> dict[str, str]:
        out: dict[str, str] = {}
        for s in sources:
            if s:
                out.update(s)
        return out

    @classmethod
    def apply_beta_headers(
        cls,
        *,
        existing_headers: dict[str, str] | None,
        need_interleaved_beta: bool,
        force_fine_grained_tools: bool = True,
    ) -> dict[str, str]:
        features: list[str] = []
        if force_fine_grained_tools:
            features.append("fine-grained-tool-streaming-2025-05-14")
        if need_interleaved_beta:
            features.append("interleaved-thinking-2025-05-14")
        if not features:
            return dict(existing_headers or {})
        out = dict(existing_headers or {})
        current = get_header_case_insensitive(out, "anthropic-beta")
        if current:
            cur = {p.strip() for p in current.split(",") if p.strip()}
            for f in features:
                cur.add(f)
            set_header_case_insensitive(
                out,
                "anthropic-beta",
                ",".join(sorted(cur)),
            )
        else:
            set_header_case_insensitive(out, "anthropic-beta", ",".join(features))
        return out

    @classmethod
    def should_inject_fine_grained_tools(
        cls,
        *,
        adapter_config: AnthropicMessagesConfig | None,
        headers: dict[str, str] | None,
    ) -> bool:
        if adapter_config is not None and adapter_config.fine_grained_tools is False:
            return False
        if headers:
            h = {k.lower(): v for k, v in headers.items()}
            if "anthropic-beta" in h:
                return True
        if adapter_config is not None and adapter_config.fine_grained_tools is True:
            return True
        return False

    @classmethod
    def should_inject_interleaved_thinking(
        cls,
        *,
        reasoning_enabled: bool | None,
        adapter_config: AnthropicMessagesConfig | None,
    ) -> bool:
        if adapter_config is not None and adapter_config.interleaved_thinking is False:
            return False
        if reasoning_enabled is not True:
            return False
        if cls.supports_adaptive_thinking(adapter_config):
            return False
        return True

    @staticmethod
    def assistant_block_to_anthropic_payload(block: object) -> dict[str, Any] | None:
        block_type = getattr(block, "type", None)
        if block_type == "text":
            text = getattr(block, "text", "")
            if isinstance(text, str) and text.strip():
                return {"type": "text", "text": sanitize_surrogates(text)}
            return None

        if block_type == "toolCall":
            tool_id = getattr(block, "id", None)
            tool_name = getattr(block, "name", None)
            tool_args = getattr(block, "arguments", {}) or {}
            if isinstance(tool_id, str) and tool_id:
                return {
                    "type": "tool_use",
                    "id": tool_id,
                    "name": tool_name or "",
                    "input": tool_args or {},
                }
            return None

        if block_type == "thinking":
            thinking = getattr(block, "thinking", "")
            if not isinstance(thinking, str) or not thinking.strip():
                return None

            signature = getattr(block, "thinking_signature", None)
            redacted = getattr(block, "redacted", False)

            if redacted:
                if isinstance(signature, str) and signature.strip():
                    return {"type": "redacted_thinking", "data": signature}
                return {"type": "text", "text": sanitize_surrogates(thinking)}

            if isinstance(signature, str) and signature.strip():
                return {
                    "type": "thinking",
                    "thinking": sanitize_surrogates(thinking),
                    "signature": signature,
                }
            return {"type": "text", "text": sanitize_surrogates(thinking)}

        return None

    @staticmethod
    def tool_result_content_to_anthropic_payload(
        content: object,
    ) -> str | list[dict[str, Any]]:
        if not isinstance(content, list):
            return "(empty)"

        if all(getattr(part, "type", None) == "text" for part in content):
            text_parts = [getattr(part, "text", "") for part in content]
            text = "\n".join(
                part for part in text_parts if isinstance(part, str) and part.strip()
            )
            return sanitize_surrogates(text) or "(empty)"

        blocks: list[dict[str, Any]] = []
        for part in content:
            part_type = getattr(part, "type", None)
            if part_type == "text":
                text = getattr(part, "text", "")
                if isinstance(text, str) and text.strip():
                    blocks.append({"type": "text", "text": sanitize_surrogates(text)})
            elif part_type == "image":
                data = getattr(part, "data", "")
                mime = getattr(part, "mime_type", "")
                if isinstance(data, str) and data and isinstance(mime, str) and mime:
                    blocks.append(
                        {
                            "type": "image",
                            "source": {
                                "type": "base64",
                                "media_type": mime,
                                "data": data,
                            },
                        }
                    )

        if not blocks:
            return "(empty)"
        if len(blocks) == 1 and blocks[0]["type"] == "text":
            return blocks[0]["text"]
        return blocks

