@dataclass
class CalcTool:
    """Simple calculator tool for demonstration."""

    name: str = "calculate"
    description: str = "Perform basic arithmetic calculations"
    parameters: dict[str, Any] = None
    label: str = "Calculator"
    prepare_arguments: None = None

    def __post_init__(self) -> None:
        if self.parameters is None:
            self.parameters = {
                "type": "object",
                "properties": {
                    "expression": {
                        "type": "string",
                        "description": "Mathematical expression to evaluate, e.g., '23 * 45' or '1 + 1'",
                    }
                },
                "required": ["expression"],
            }

    async def execute(
        self,
        tool_call_id: str,
        params: dict[str, Any],
        signal: object | None = None,
        on_update: Any = None,
    ) -> AgentToolResult[dict[str, Any]]:
        expression = params.get("expression", "")
        try:
            # Safe eval for basic arithmetic
            result = eval(expression, {"__builtins__": {}}, {})
            return AgentToolResult(
                content=[TextPart(type="text", text=str(result))],
                details={"expression": expression, "result": result},
            )
        except Exception as e:
            return AgentToolResult(
                content=[TextPart(type="text", text=f"Error: {e}")],
                details={"error": str(e)},
            )


def _resolve_api_key() -> str:
    api_key = (
        os.environ.get("KIMI_API_KEY")
        or os.environ.get("MOONSHOT_API_KEY")
        or os.environ.get("OPENAI_API_KEY")
    )
    if not api_key:
        raise RuntimeError("请先导出 KIMI_API_KEY 或 MOONSHOT_API_KEY 环境变量")
    return api_key


def _build_model() -> Model:
    """Build public Model for Kimi via Moonshot OpenAI-compatible chat API."""
    return replace(
        get_model("moonshot", "openai-completions", MODEL_ID),
        base_url=BASE_URL,
    )


async def main() -> None:
    model = _build_model()

    # Explicit request auth is an AI SDK concern; the agent only forwards options.
    agent = Agent(
        initial_state=AgentState(
            system_prompt=(
                "你是 Kimi，由 Moonshot AI 提供的人工智能助手。"
                "你更擅长中文和英文的对话，会为用户提供安全、有帮助、准确的回答。"
            ),
            model=model,
            thinking_level="off",
            tools=[CalcTool()],
        ),
        call_options=CallOptions(auth=ApiKeyAuth(_resolve_api_key())),
    )

    # Subscribe to events for streaming output
    def on_event(event: dict, signal: object) -> None:
        event_type = event.get("type")
        if event_type == "message_update":
            assistant_event = event.get("assistant_message_event", {})
            if assistant_event.get("type") == "text_delta":
                delta = assistant_event.get("delta", "")
                print(delta, end="", flush=True)
        elif event_type == "message_end":
            message = event.get("message")
            if getattr(message, "role", None) == "assistant" and getattr(
                message, "error_message", None
            ):
                print(f"[错误: {message.error_message}]")
            else:
                print()  # New line after message completes
        elif event_type == "tool_execution_start":
            print(f"\n[使用工具: {event.get('tool_name')}({event.get('args')})]")
        elif event_type == "tool_execution_end":
            result = event.get("result")
            if result and hasattr(result, "content"):
                content_text = "".join(
                    p.text for p in result.content if getattr(p, "type", None) == "text"
                )
                print(f"[工具结果: {content_text}]")

    agent.subscribe(on_event)

    print("=== Kimi Agent Demo (OpenAI Chat Completions) ===")
    print(f"Model: {MODEL_ID}")
    print(f"Base URL: {BASE_URL}")
    print("Type 'quit' to exit\n")

    # Demo 1: Simple greeting
    print("User: 你好，1+1等于多少？")
    print("Kimi: ", end="", flush=True)
    await agent.prompt("你好，1+1等于多少？")
    print()

    # Demo 2: Tool usage
    print("\nUser: 请用计算器工具计算 23 * 45")
    print("Kimi: ", end="", flush=True)
    await agent.prompt("请用计算器工具计算 23 * 45")
    print()

    # Demo 3: Interactive mode (only in TTY)
    if sys.stdin.isatty():
        print("\n=== 交互模式 ===")
        while True:
            try:
                user_input = input("\nUser: ").strip()
                if user_input.lower() in ("quit", "exit", "q"):
                    break
                if not user_input:
                    continue

                print("Kimi: ", end="", flush=True)
                await agent.prompt(user_input)
                print()

            except KeyboardInterrupt:
                print("\n\nExiting...")
                break
            except Exception as e:
                print(f"\nError: {e}")
    else:
        print("\n=== 非交互模式，跳过交互演示 ===")

    print("\n=== 对话结束 ===")
    print(f"Total messages: {len(agent.messages)}")


if __name__ == "__main__":
    try:
        asyncio.run(main())
    except KeyboardInterrupt:
        print("\nInterrupted.", file=sys.stderr)
        raise SystemExit(130)
    except RuntimeError as e:
        print(f"ERROR: {e}", file=sys.stderr)
        raise SystemExit(1)

from __future__ import annotations

import asyncio
import json
from typing import Any

from ..assembler import TextAssembler
from ..event_stream import create_assistant_message_event_stream
from ..raw_parts import RawDone, RawError, RawTextDelta
from ..registry import ApiProvider
from ..types import Context, Model, SimpleStreamOptions, StreamOptions


def create_httpx_provider(client_factory: Any | None = None) -> ApiProvider:
    def stream(model: Model, context: Context, options: StreamOptions | None = None):
        try:
            import httpx
        except ModuleNotFoundError as exc:  # pragma: no cover
            raise RuntimeError("httpx is not installed") from exc

        stream_obj, writer = create_assistant_message_event_stream()
        assembler = TextAssembler(writer=writer, model=model, context=context, provider_name=model.provider)

        async def run() -> None:
            assembler.start()
            client = client_factory() if client_factory is not None else httpx.AsyncClient()
            owns_client = client_factory is None
            stop_reason = "stop"
            try:
                if _is_cancelled(options):
                    assembler.fail(RawError(message="aborted"))
                    return
                headers = {
                    "x-api-key": options.api_key if options and options.api_key else "",
                    "anthropic-version": "2023-06-01",
                    "content-type": "application/json",
                    "accept": "text/event-stream",
                }
                body = {
                    "model": model.id,
                    "messages": context.messages,
                    "system": context.system_prompt,
                    "max_tokens": options.max_tokens if options and options.max_tokens else model.max_tokens,
                    "stream": True,
                }
                async with client.stream(
                    "POST",
                    f"{model.base_url.rstrip('/')}/v1/messages",
                    headers=headers,
                    json=body,
                    timeout=30.0,
                ) as response:
                    response.raise_for_status()
                    current_event: str | None = None
                    current_data: list[str] = []
                    response_id: str | None = None
                    usage_payload: dict[str, int] | None = None
                    async for line in response.aiter_lines():
                        if _is_cancelled(options):
                            assembler.fail(RawError(message="aborted", response_id=response_id, usage=usage_payload))
                            return
                        if not line:
                            if current_event and current_data:
                                payload = json.loads("\n".join(current_data))
                                if current_event == "message_start":
                                    response_id = _extract_response_id(payload)
                                if current_event == "content_block_delta":
                                    delta = payload.get("delta", {})
                                    if delta.get("type") == "text_delta":
                                        assembler.emit_text(RawTextDelta(text=delta.get("text", "")))
                                elif current_event == "message_delta":
                                    stop_reason = _map_stop_reason(payload.get("delta", {}).get("stop_reason"))
                                    usage_payload = _merge_usage(usage_payload, payload.get("usage"))
                                elif current_event == "message_stop":
                                    if _is_cancelled(options):
                                        assembler.fail(RawError(message="aborted", response_id=response_id, usage=usage_payload))
                                        return
                                    assembler.finish(
                                        RawDone(stop_reason=stop_reason, response_id=response_id, usage=usage_payload)
                                    )
                                    return
                            current_event = None
                            current_data = []
                            continue
                        if line.startswith("event:"):
                            current_event = line.split(":", 1)[1].strip()
                        elif line.startswith("data:"):
                            current_data.append(line.split(":", 1)[1].lstrip())
                    assembler.finish(RawDone(stop_reason=stop_reason, response_id=response_id, usage=usage_payload))
            except Exception as exc:
                assembler.fail(RawError(message=str(exc)))
            finally:
                if owns_client:
                    await client.aclose()

        asyncio.create_task(run())
        return stream_obj

    def stream_simple(model: Model, context: Context, options: SimpleStreamOptions | None = None):
        return stream(model, context, options)

    return ApiProvider(api="anthropic-messages", stream=stream, stream_simple=stream_simple)


def _map_stop_reason(stop_reason: Any) -> str:
    if stop_reason in ("end_turn", "stop_sequence", "stop"):
        return "stop"
    if stop_reason == "max_tokens":
        return "length"
    if stop_reason == "tool_use":
        return "toolUse"
    if stop_reason == "aborted":
        return "aborted"
    return "error"


def _is_cancelled(options: StreamOptions | None) -> bool:
    return bool(getattr(options, "signal", None) and getattr(options.signal, "cancelled", False))


def _extract_response_id(payload: dict[str, Any]) -> str | None:
    message = payload.get("message")
    if isinstance(message, dict):
        value = message.get("id")
        if value:
            return str(value)
    value = payload.get("id")
    return str(value) if value else None


def _merge_usage(existing: dict[str, int] | None, incoming: Any) -> dict[str, int] | None:
    if incoming is None:
        return existing
    payload = {
        "input_tokens": _usage_value(incoming, "input_tokens"),
        "output_tokens": _usage_value(incoming, "output_tokens"),
        "cache_read_input_tokens": _usage_value(incoming, "cache_read_input_tokens"),
        "cache_creation_input_tokens": _usage_value(incoming, "cache_creation_input_tokens"),
    }
    if existing is None:
        return payload
    merged = existing.copy()
    for key, value in payload.items():
        merged[key] = max(int(merged.get(key, 0) or 0), int(value or 0))
    return merged


def _usage_value(incoming: Any, key: str) -> int:
    if isinstance(incoming, dict):
        return int(incoming.get(key, 0) or 0)
    return int(getattr(incoming, key, 0) or 0)
